import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load the OpenAPI specification for validation
API_SPEC_PATH = Path(__file__).parent / "api.json"
validator = SwaggerSchemaValidator(API_SPEC_PATH)

# Load test data from JSON file
TEST_DATA_FILENAME = "pet_petId.json"
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / TEST_DATA_FILENAME

def _load_json_file(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

_ENDPOINT_DATA = _load_json_file(_endpoint_data_path)
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [case['scenario'] for case in _ENDPOINT_DATA]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_delete_pet(api_client, config_test_data, scenario_case):
    """
    Test the DELETE /pet/{petId} endpoint with various scenarios.
    """
    petId = scenario_case.get('petId', config_test_data['petId'])
    api_key = scenario_case.get('api_key', None)
    expected_status_code = scenario_case['statusCode']
    
    endpoint = f"/pet/{petId}"
